css:
    body {
        background-color: #f1f5f9;
        display: flex;
        justify-content: center;
        align-items: center;
        min-height: 100vh;
        margin: 0;
        -webkit-font-smoothing: antialiased;
    }

    .cr80-card {
        width: 337px; /* 85.6mm */
        height: 539px; /* 136.7mm (Extended Portrait) */
        background-color: #ffffff;
        border-radius: 1.25rem;
        box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.15);
        position: relative;
        overflow: hidden;
        display: flex;
        flex-direction: column;
        border: 1px solid #e2e8f0;
    }

    .header-wave {
        background-color: #006c49; /* Deep Emerald Green */
        height: 140px;
        width: 100%;
        position: relative;
        display: flex;
        justify-content: center;
        align-items: center;
        padding-top: 1rem;
    }

    .photo-border {
        width: 130px;
        height: 130px;
        background-color: #ffffff;
        border-radius: 50%;
        display: flex;
        justify-content: center;
        align-items: center;
        position: absolute;
        bottom: -65px;
        box-shadow: 0 4px 10px rgba(0,0,0,0.1);
    }

    .photo-inner {
        width: 120px;
        height: 120px;
        border-radius: 50%;
        overflow: hidden;
        background-color: #e2e8f0;
    }

    .material-symbols-outlined {
        font-variation-settings: 'FILL' 1, 'wght' 400, 'GRAD' 0, 'opsz' 24;
        vertical-align: middle;
    }

    .hologram-shimmer {
        position: absolute;
        bottom: 20px;
        right: 20px;
        width: 40px;
        height: 40px;
        background: linear-gradient(135deg, rgba(0, 255, 255, 0.3) 0%, rgba(255, 0, 255, 0.3) 50%, rgba(255, 215, 0, 0.3) 100%);
        border-radius: 50%;
        filter: blur(2px);
        opacity: 0.5;
        animation: rotate 4s linear infinite;
    }

    @keyframes rotate {
        from { transform: rotate(0deg); }
        to { transform: rotate(360deg); }
    }

    .qr-area {
        background-color: #ffffff;
        padding: 8px;
        border-radius: 8px;
        border: 1px solid #f1f5f9;
    }


body {
  min-height: max(884px, 100dvh);
}
